    };
    const proof = await runIVXFactoryJob({
      taskId: 'test-mig-2',
      goal: 'invalid migration',
      ownerId: 'iperez4242@gmail.com',
      approvalPhrase: IVX_FACTORY_APPROVAL_PHRASE,
