// Commit the factory engine module via owner-gated GitHub API.
const fs = require('fs');
const path = require('path');

const TOKEN = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

async function commitFile(filePath, b64Path, message) {
  const content = fs.readFileSync(b64Path, 'utf8').trim();
  const body = {
    action: 'github_commit_file',
    input: {
      path: filePath,
      content,
      contentEncoding: 'gzip-base64',
      message,
    },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${TOKEN}`,
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = JSON.parse(text); } catch { json = { raw: text }; }
  console.log(`[${filePath}] HTTP ${res.status}`);
  console.log(JSON.stringify(json, null, 2).slice(0, 1200));
  return json;
}

(async () => {
  // 1. factory engine module
  const r1 = await commitFile(
    'backend/services/ivx-autonomous-coder-factory.ts',
    '/tmp/factory_module.b64',
    'feat(autonomous-coder): add factory engine extension — create_directory/create_module/install_dependency/run_supabase_migration/run_build/create_tool/upgrade_self (owner-gated CONFIRM_IVX_FACTORY_MODE)',
  );
  // 2. factory engine tests
  const r2 = await commitFile(
    'backend/services/ivx-autonomous-coder-factory.test.ts',
    '/tmp/factory_test.b64',
    'test(autonomous-coder-factory): 33 regression tests — approval guard, capability manifest, tool registry, all 7 operation kinds, multi-op pipeline, answer format',
  );
  // 3. worker wiring
  const r3 = await commitFile(
    'backend/services/ivx-senior-developer-worker.ts',
    '/tmp/worker.b64',
    'feat(worker): wire factory execution mode into the worker — executionMode "factory" routes through runIVXFactoryJob + summarizeFactoryJobProof',
  );
  console.log('---');
  console.log('commit1:', r1?.commitSha || r1?.commit_sha || r1?.sha || 'no-sha');
  console.log('commit2:', r2?.commitSha || r2?.commit_sha || r2?.sha || 'no-sha');
  console.log('commit3:', r3?.commitSha || r3?.commit_sha || r3?.sha || 'no-sha');
})();

