// Deploy to Render via owner-gated render_trigger_deploy, then verify 3-way parity.
import fs from 'node:fs';

const TOKEN = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

async function triggerDeploy() {
  const body = {
    action: 'render_trigger_deploy',
    input: {},
    confirm: true,
    confirmText: 'CONFIRM_IVX_RENDER_DEPLOY',
  };
  const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${TOKEN}`,
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = JSON.parse(text); } catch { json = { raw: text }; }
  console.log('[render_trigger_deploy] HTTP', res.status);
  console.log(JSON.stringify(json, null, 2).slice(0, 1500));
  return json;
}

async function getRuntimeCommit() {
  const res = await fetch(`${API}/version`);
  const data = await res.json();
  return data.commit ?? null;
}

async function getHealth() {
  const res = await fetch(`${API}/health`);
  const data = await res.json();
  return { status: data.status, commit: data.commitSha ?? null };
}

async function getGitHubHead() {
  const res = await fetch('https://api.github.com/repos/ibb142/rork-global-real-estate-invest/commits/main');
  if (!res.ok) return null;
  const data = await res.json();
  return data.sha ?? null;
}

async function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

const deploy = await triggerDeploy();
console.log('--- waiting 45s for render to build ---');
await sleep(45000);

const gh = await getGitHubHead();
const rt = await getRuntimeCommit();
const health = await getHealth();
console.log('--- 3-WAY PARITY CHECK ---');
console.log('GitHub HEAD:    ', gh);
console.log('Render runtime: ', rt);
console.log('Health commit:  ', health.commit);
console.log('Health status:  ', health.status);
if (gh && rt && gh === rt && health.status === 'healthy') {
  console.log('PARITY:         MATCH (GitHub = Render = Runtime) ✅');
} else {
  console.log('PARITY:         DRIFT (may still be propagating; will retry)');
  for (let i = 0; i < 6; i++) {
    await sleep(30000);
    const rt2 = await getRuntimeCommit();
    const h2 = await getHealth();
    console.log(`retry ${i+1}: runtime=${rt2} health=${h2.status}`);
    if (gh && rt2 && gh === rt2 && h2.status === 'healthy') {
      console.log('PARITY:         MATCH (propagated) ✅');
      break;
    }
  }
}

