// Run a REAL factory-mode job through the production IVX engine via owner-ai chat.
// Goal: use the factory engine to create a new IVX-owned tool + upgrade the
// capability manifest — the two operations that DON'T require external credentials
// (build/supabase/deps need runners that are owner-gated). This proves the factory
// engine executes live on production with a structured proof.
import fs from 'node:fs';

const TOKEN = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

// Submit via owner-ai chat with a unique runId so dedup doesn't attach to an old job.
const runId = `factory-live-${Date.now()}`;
const message = `factory: Use the IVX Factory Engine to (1) register a new IVX-owned tool named "ivx-investor-scorer" version "1.0.0" with capability "Score investor prospects against the IVX matching algorithm" and handlerName "investor-scorer-handler", and (2) upgrade the autonomous coder capability manifest by appending a new capability id "investor_scorer" label "Score investor prospects against the IVX matching algorithm" version "1.0.0" operations ["create_tool"]. Approval phrase: CONFIRM_IVX_FACTORY_MODE. runId=${runId}`;

const res = await fetch(`${API}/api/ivx/owner-ai`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${TOKEN}`,
  },
  body: JSON.stringify({ message }),
});

const text = await res.text();
let json;
try { json = JSON.parse(text); } catch { json = { raw: text.slice(0, 2000) }; }
console.log('HTTP', res.status);
console.log('--- response (first 3000 chars) ---');
console.log(JSON.stringify(json, null, 2).slice(0, 3000));

// Extract taskId + executionStatus
const execStatus = json?.executionStatus ?? json?.executionStatusPayload ?? null;
const taskId = execStatus?.taskId ?? json?.taskId ?? null;
console.log('--- extracted ---');
console.log('taskId:', taskId);
console.log('executionStatus:', JSON.stringify(execStatus, null, 2).slice(0, 1500));

// If we have a taskId, poll the job until terminal.
if (taskId) {
  console.log('--- polling job status ---');
  for (let i = 0; i < 20; i++) {
    await new Promise((r) => setTimeout(r, 3000));
    const jobRes = await fetch(`${API}/api/ivx/senior-developer/worker/jobs/${taskId}`, {
      headers: { Authorization: `Bearer ${TOKEN}` },
    });
    const jobData = await jobRes.json();
    const job = jobData.job ?? jobData;
    console.log(`poll ${i+1}: status=${job.status} stage=${job.stage} progress=${job.progressPercent}%`);
    if (job.status === 'completed' || job.status === 'failed' || job.status === 'blocked' || job.status === 'cancelled') {
      console.log('--- TERMINAL JOB RESULT ---');
      console.log(JSON.stringify(job, null, 2).slice(0, 4000));
      break;
    }
  }
}

