// Commit owner-ai.ts (factory routing) + factory test file fix via owner-gated GitHub API.
import fs from 'node:fs';

const TOKEN = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

async function commitFile(filePath, b64Path, message) {
  const content = fs.readFileSync(b64Path, 'utf8').trim();
  const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${TOKEN}` },
    body: JSON.stringify({
      action: 'github_commit_file',
      input: { path: filePath, content, contentEncoding: 'gzip-base64', message },
      confirm: true,
      confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
    }),
  });
  const data = await res.json();
  console.log(`[${filePath}] HTTP ${res.status} sha=${data?.result?.commitSha ?? 'none'}`);
  return data;
}

const r1 = await commitFile(
  'backend/api/ivx-owner-ai.ts',
  '/tmp/owner_ai.b64',
  'feat(owner-ai): route factory-mode prompts through the IVX Factory Engine — factoryTrigger detects factory intent, extracts create_tool + upgrade_self operations from the prompt, enqueues executionMode=factory job with CONFIRM_IVX_FACTORY_MODE approval',
);
const r2 = await commitFile(
  'backend/services/ivx-autonomous-coder-factory.test.ts',
  '/tmp/factory_test2.b64',
  'fix(autonomous-coder-factory.test): add required registeredAt/approvedBy/addedAt fields to tool + capability descriptors in tests (TS2739/TS2741)',
);
console.log('---');
console.log('owner-ai sha:', r1?.result?.commitSha ?? 'none');
console.log('test fix sha:', r2?.result?.commitSha ?? 'none');

