// Run a REAL factory-mode job through the production IVX engine via owner-ai chat.
// Use a unique runId so dedup doesn't attach to the cancelled job.
import fs from 'node:fs';

const TOKEN = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

const runId = `factory-live-${Date.now()}`;
const message = `factory: Use the IVX Factory Engine to (1) register a new IVX-owned tool named "ivx-investor-scorer" version "1.0.0" with capability "Score investor prospects against the IVX matching algorithm" and handlerName "investor-scorer-handler", and (2) upgrade the autonomous coder capability manifest by appending a new capability id "investor_scorer" label "Score investor prospects against the IVX matching algorithm" version "1.0.0". Approval phrase: CONFIRM_IVX_FACTORY_MODE. runId=${runId}`;

const res = await fetch(`${API}/api/ivx/owner-ai`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${TOKEN}` },
  body: JSON.stringify({ message }),
});

const text = await res.text();
let json;
try { json = JSON.parse(text); } catch { json = { raw: text.slice(0, 2000) }; }
console.log('HTTP', res.status);
console.log('--- answer (first 1500 chars) ---');
console.log((json?.answer ?? '').slice(0, 1500));
console.log('--- executionStatus ---');
const execStatus = json?.executionStatus ?? null;
console.log(JSON.stringify(execStatus, null, 2).slice(0, 1200));

const taskId = execStatus?.taskId ?? null;
console.log('taskId:', taskId);

if (taskId) {
  console.log('--- polling job status ---');
  for (let i = 0; i < 15; i++) {
    await new Promise((r) => setTimeout(r, 3000));
    const jobRes = await fetch(`${API}/api/ivx/senior-developer/worker/jobs/${taskId}`, {
      headers: { Authorization: `Bearer ${TOKEN}` },
    });
    const jobData = await jobRes.json();
    const job = jobData.job ?? jobData;
    console.log(`poll ${i+1}: status=${job.status} stage=${job.stage} progress=${job.progressPercent}% detail=${(job.stageDetail ?? '').slice(0, 100)}`);
    if (['completed', 'failed', 'blocked', 'cancelled'].includes(job.status)) {
      console.log('--- TERMINAL JOB RESULT ---');
      const result = job.result ?? {};
      console.log('finalStatus:', result.finalStatus);
      console.log('changedFiles:', JSON.stringify(result.changedFiles));
      console.log('buildRun:', result.buildRun);
      console.log('commitSha:', result.commitSha);
      console.log('generatedFeatureSlug:', result.generatedFeatureSlug);
      console.log('error:', result.error);
      break;
    }
  }
}

